	@Test
	void dedupOrderByOffsetAndLimitStack() throws Exception {
		Emit distinctOrdered = emit(0).distinct()
				.withMods(new OutputMods(new int[] { 0 }, null, false, 2L, 1L));
		Kernel ir = new Kernel(1, List.of(new EnumerateDomain(0, 0)), distinctOrdered);
		List<long[]> rows = run(ir, context().domains(new long[] { 3, 1, 2, 3, 2, 1 }));
		// Distinct {3,1,2} -> ascending {1,2,3} -> offset 1 -> {2,3} -> limit 2 -> {2,3}.
		assertOrderedRows(rows, new long[][] { { 2 }, { 3 } });
	}

	@Test
	void orderByDescendingTopKAndValueOrderViaHooks() throws Exception {
		Kernel descending = new Kernel(1, List.of(new EnumerateDomain(0, 0)),
				emit(0).withMods(new OutputMods(new int[] { 0 }, new boolean[] { true }, false, 2L, 0L)));
		assertOrderedRows(run(descending, context().domains(new long[] { 5, 9, 1, 7 })),
				new long[][] { { 9 }, { 7 } });

		// Unsigned id order puts -1 last ascending; hook value order (signed) puts it first.
		long[] withNull = { 5, -1, 7 };
		Kernel unsigned = new Kernel(1, List.of(new EnumerateDomain(0, 0)),
				emit(0).withMods(new OutputMods(new int[] { 0 }, null, false, -1L, 0L)));
		assertOrderedRows(run(unsigned, context().domains(withNull)),
				new long[][] { { 5 }, { 7 }, { -1 } });
		Kernel valueOrder = new Kernel(1, List.of(new EnumerateDomain(0, 0)),
				emit(0).withMods(new OutputMods(new int[] { 0 }, null, true, -1L, 0L)));
		assertOrderedRows(run(valueOrder, context().domains(withNull).hooks(new TestHooks())),
				new long[][] { { -1 }, { 5 }, { 7 } });
	}

