	@Test
	void unionLeftProbeExistsIntoGroupedCountDistinct() throws Exception {
		// The corpus skeleton-6 shape: UNION seed -> OPTIONAL members -> EXISTS witness -> COUNT(DISTINCT) HAVING.
		NativeLmdbQuerySource.NativeAdjacency members = new FixtureAdjacency(
				new long[][] { { 100, 1, 2 }, { 200, 3 } });
		Union union = new Union(List.of(
				List.of((Node) new EnumerateDomain(0, 0)),
				List.of((Node) new EnumerateDomain(1, 0))));
		Kernel ir = new Kernel(3,
				List.of(union, new LeftProbe(1, Operand.col(0), 1),
						new Exists(false, List.of(new Probe(0, Operand.col(1), 2)))),
				new Aggregate(new int[] { 0 }, new AggregateOutput[] { AggregateOutput.countDistinct(1) }, null,
						OutputMods.none()).having(0, LmdbNativeKernelIr.OP_GE, 1));
		List<long[]> rows = run(ir, context().adjacencies(follows(), members)
				.domains(new long[] { 100, 200 }, new long[] { 200 }));
		// Group 200 is seeded by both branches; COUNT(DISTINCT) collapses the duplicate member.
		assertRows(rows, new long[][] { { 100, 2 }, { 200, 1 } });
	}

	@Test
	void subqueryResultFeedsOuterKernelAsDomain() throws Exception {
		Kernel inner = new Kernel(2, List.of(new EnumerateAdjKeys(0, 0, 1)),
				new Aggregate(new int[] { 0 }, new AggregateOutput[] { AggregateOutput.countStar() }, null,
						OutputMods.none()).having(0, LmdbNativeKernelIr.OP_GE, 2));
		List<long[]> innerRows = run(inner, context().adjacencies(follows()));
		long[] domain = new long[innerRows.size()];
		for (int i = 0; i < innerRows.size(); i++) {
			domain[i] = innerRows.get(i)[0];
		}
		// Only key 1 has two or more neighbors; the outer kernel probes just that group.
		Kernel outer = new Kernel(2, List.of(new EnumerateDomain(0, 0), new Probe(0, Operand.col(0), 1)),
				emit(0, 1));
		assertRows(run(outer, context().adjacencies(follows()).domains(domain)),
				new long[][] { { 1, 2 }, { 1, 3 } });
	}

	@Test
	void existsOverUnionAndPathExpandComposes() throws Exception {
		// Guard: keep sources that can reach node 4 through either a direct edge (branch 1) or a + path (branch 2).
		NativeLmdbQuerySource.NativeAdjacency cyclic = new FixtureAdjacency(
				new long[][] { { 1, 2 }, { 2, 3 }, { 3, 1, 4 } });
		Union witness = new Union(List.of(
				List.of((Node) new Probe(0, Operand.col(0), 1), new FilterCompareId(false, Operand.col(1),
						Operand.constant(0))),
				List.of((Node) new PathExpand(0, Operand.col(0), 1, 1), new FilterCompareId(false, Operand.col(1),
						Operand.constant(0)))));
		Kernel ir = new Kernel(2,
				List.of(new EnumerateDomain(0, 0), new Exists(false, List.of(witness))), emit(0));
		List<long[]> rows = run(ir, context().adjacencies(cyclic)
				.constants(4L)
				.domains(new long[] { 1, 2, 3, 4 }));
		// 3 reaches 4 directly; 1 and 2 only transitively; 4 has no outgoing edges at all.
		assertRows(rows, new long[][] { { 1 }, { 2 }, { 3 } });
	}

